<?php require 'backend/config/database.php'; \=getDB(); \=\->prepare('SELECT sc.id, sc.day, sc.start_time, sc.end_time, sc.class_id, cl.name AS class_name, sc.subject_id, su.name AS subject_name, sc.teacher_id, t.name AS teacher_name FROM schedules sc JOIN classes cl ON sc.class_id=cl.id JOIN subjects su ON sc.subject_id=su.id JOIN teachers t ON sc.teacher_id=t.id WHERE sc.teacher_id=5 AND sc.day=\'Sabtu\' ORDER BY sc.start_time'); \->execute(); echo json_encode(\->fetchAll());
